durable_reproduction.common_bash:
set -euo pipefail
TOOLS=${SOUJI_S12_TOOLS:-/home/vgpnk/Projects/shokunin/souji-shokunin/tools}
T=$(mktemp -d -p /var/tmp souji-r9-s12-repro.XXXXXX)
export TMPDIR=/var/tmp HOME="$T/home" GIT_OPTIONAL_LOCKS=0 GIT_TERMINAL_PROMPT=0 GIT_CONFIG_NOSYSTEM=1 GIT_CONFIG_GLOBAL=/dev/null
export GIT_AUTHOR_NAME='S12 Fixture' GIT_AUTHOR_EMAIL=s12@example.invalid GIT_COMMITTER_NAME='S12 Fixture' GIT_COMMITTER_EMAIL=s12@example.invalid
unset GIT_DIR GIT_WORK_TREE GIT_INDEX_FILE GIT_NAMESPACE SOUJI_Q_TEST_HOOK SOUJI_Q_SELFTEST_ACTIVE SOUJI_QUARANTINE_ALLOW_LIVE SOUJI_CLI_BIN
R="$T/fleet/probe-shokunin"
mkdir -p "$R" "$HOME"
git init -q --initial-branch=main "$R"
LEDGER="$T/ledger.tsv"
printf 'source_path\tsource_sha256\tvault_path\tvault_sha256\texported_at\tnote\n' > "$LEDGER"
export SHOKUNIN_ROOT="$T/fleet" SOUJI_LEDGER="$LEDGER" SOUJI_Q_SHOKUNIN_ROOT="$T/fleet" SOUJI_Q_LEDGER="$LEDGER" SOUJI_VERIFY_BIN="$TOOLS/souji-verify.sh"
commit_fixture() { git -C "$R" add -A; C=$(printf 'S12 fixture\n' | git -C "$R" commit-tree "$(git -C "$R" write-tree)"); git -C "$R" update-ref refs/heads/main "$C"; if [ "$1" = pushed ]; then git -C "$R" update-ref refs/remotes/origin/main "$C"; git -C "$R" symbolic-ref refs/remotes/origin/HEAD refs/remotes/origin/main; fi; }
A() { bash "$TOOLS/souji-verify.sh" --json -- "$1"; }
B() { bash "$TOOLS/souji-vault-verify.sh" --json --fallback -- "$1"; }
Q() { bash "$TOOLS/souji-quarantine.sh" --hold 0 -- "$R" "$1"; }
